# Print options match the PDF: all rows, 88 columns, four significant digits.
options(width = 88, tibble.width = 88, pillar.width = 88,
        tibble.print_max = Inf, tibble.print_min = Inf,
        pillar.sigfig = 4, cli.unicode = FALSE, crayon.enabled = FALSE)

# SECTION 01: A small survey, one shared input
library(statart)
library(dplyr)
library(tibble)
survey <- tibble(
  id = 1:8,
  region = c("North", "North", "North", "North",
             "South", "South", "South", "South"),
  age = c(24, 31, 45, 52, 28, 36, 49, 57),
  income_k = c(32, 48, 55, 82, 29, 46, NA, 88),
  employed = c("Yes", "Yes", "No", "Yes", "Yes", "No", NA, "Yes")
)
survey

# SECTION 02: Numeric summaries
survey |> summ(age, income_k)

survey |>
  tabstat(income_k, .by = region,
          .stat = c("n", "mean", "p50"))

# SECTION 03: Frequencies and cross-table margins
survey |> tab(employed)

survey |> fre2(region, employed)

# SECTION 04: Use the result inside a research pipeline
region_stats <- survey |>
  tabstat(income_k, .by = region, .stat = c("n", "mean")) |>
  select(region, observed_n = n, region_mean = mean)
analysis_data <- survey |>
  left_join(region_stats, by = "region") |>
  mutate(income_gap = income_k - region_mean)
analysis_data |>
  select(id, region, income_k, observed_n, region_mean, income_gap)

output_dir <- ".opencode/results/console-showcase/tables"
dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)
write.csv(region_stats, file.path(output_dir, "regional_summary.csv"),
          row.names = FALSE, na = "")
